using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
using ThorCapture.Features.Library;
using ThorCapture.Media;

namespace ThorCapture
{
    internal static class LibraryManagementTests
    {
        sealed class Step : IProgress<int> { readonly Action<int> action; internal Step(Action<int> action){this.action=action;}public void Report(int n){action(n);} }
        sealed class BytesStep : IProgress<long> { readonly CancellationTokenSource cancel;internal BytesStep(CancellationTokenSource cancel){this.cancel=cancel;}public void Report(long n){cancel.Cancel();} }
        sealed class Provider : IReadOnlyMediaProvider
        {
            public Guid Id=Guid.NewGuid();public Guid InstanceId{get{return Id;}}internal byte[] Bytes;internal RemoteMedia Item;internal readonly List<string> Listed=new List<string>();internal readonly List<long> Offsets=new List<long>();internal bool Hang,Rebind;
            public Task<ReadOnlyCollection<RemoteMedia>> ListAsync(string dir,CancellationToken token){Listed.Add(dir);if(Rebind)Id=Guid.NewGuid();return Task.FromResult(new ReadOnlyCollection<RemoteMedia>(new[]{Item}));}
            public Task<Stream> OpenReadAsync(RemoteMedia selected,long offset,CancellationToken token){Offsets.Add(offset);if(Hang)return new TaskCompletionSource<Stream>().Task;Stream stream=new MemoryStream(Bytes,false);stream.Position=offset;return Task.FromResult(stream);}
        }
        static string Folder(){string dir=Path.Combine(Tests.Root,"library-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);return dir;}
        static byte[] Png(Color color){using(Bitmap bitmap=new Bitmap(18,18))using(Graphics g=Graphics.FromImage(bitmap))using(MemoryStream s=new MemoryStream()){g.Clear(color);bitmap.Save(s,ImageFormat.Png);return s.ToArray();}}
        static string Hash(byte[] bytes){using(SHA256 hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-","");}
        static async Task<MediaGroup> Pair(MediaRepository repo,string prefix){MediaRepositoryResult result=await repo.PublishGroupAsync(repo.GetSnapshot().RepositoryId,new[]{new PublishedPngInput(prefix+"-upper.png",ScreenRole.Upper,Png(Color.Red)),new PublishedPngInput(prefix+"-lower.png",ScreenRole.Lower,Png(Color.Blue))},CancellationToken.None);return result.Group;}
        internal static void Run(){Task.Run((Func<Task>)RunAsync).GetAwaiter().GetResult();}
        static async Task RunAsync()
        {
            string root=Folder(),data=Folder(),destRoot=Folder(),destData=Folder();using(MediaRepository repo=new MediaRepository(root,data))using(MediaRepository dest=new MediaRepository(destRoot,destData))
            {
                await repo.RefreshAsync(CancellationToken.None);await dest.RefreshAsync(CancellationToken.None);MediaGroup group=await Pair(repo,"original");
                MediaTags.BatchResult tagged=await MediaTags.ApplyBatchAsync(repo,new[]{new AnnotationRequest(group.GroupId,group.Revision,true,new[]{" tag ","TAG","测试"})},CancellationToken.None);group=tagged.Results.Single().Group;
                Tests.Check(tagged.Outcome==LibraryOperationOutcome.Success&&group.Favorite&&group.Tags.Count==2,"batch annotations use real repository CAS with tag normalization");
                tagged=await MediaTags.ApplyBatchAsync(repo,new[]{new AnnotationRequest(group.GroupId,1,false,new string[0])},CancellationToken.None);Tests.Check(tagged.Outcome==LibraryOperationOutcome.Conflict&&repo.GetSnapshot().FindGroup(group.GroupId).Favorite,"stale batch annotation cannot replace current user metadata");
                string upper=Path.Combine(root,"original-upper.png");new CaptureMetadata{Status="identified",Package="fixture.game",CapturedUtc=DateTime.UtcNow,ObservedUtc=DateTime.UtcNow}.Save(upper);File.WriteAllText(upper+".input.csv","fixture timeline");File.WriteAllBytes(Path.ChangeExtension(upper,".wav"),new byte[]{1,2,3});
                GroupOperationPlan plan=await GroupOperations.PlanRenameAsync(repo,group.GroupId,"中文名称",CancellationToken.None);Tests.Check(plan.Conflicts.Count==0&&plan.Moves.Count==5,"rename plan includes paired originals and only their fixed known sidecars and audio");
                GroupOperationResult result=await GroupOperations.ExecuteAsync(repo,plan,false,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.ConfirmationRequired&&File.Exists(upper),"rename execution requires confirmation before writing");
                result=await GroupOperations.ExecuteAsync(repo,plan,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Success&&File.Exists(Path.Combine(root,"中文名称-upper.png.input.csv"))&&!File.Exists(upper),"confirmed group rename moves originals and sidecars together");
                group=result.RepositoryResult.Group;Tests.Check(group.Favorite&&group.Tags.Count==2&&group.Tracks.All(x=>x.TrackId.Length==32),"rename retains stable UUIDs and user annotations");
                result=await GroupOperations.RecoverAsync(repo,plan.TransactionId,true,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Success&&File.Exists(upper)&&result.RepositoryResult.Group.Tracks.All(x=>x.RelativePath.StartsWith("original")),"committed rename can roll back without deleting either original");
                result=await GroupOperations.RecoverAsync(repo,plan.TransactionId,true,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Success,"rename rollback is idempotent");
                group=repo.GetSnapshot().FindGroup(group.GroupId);plan=await GroupOperations.PlanRenameAsync(repo,group.GroupId,"partial",CancellationToken.None);
                using(CancellationTokenSource cancel=new CancellationTokenSource()){result=await GroupOperations.ExecuteAsync(repo,plan,true,cancel.Token,new Step(n=>cancel.Cancel()));Tests.Check(result.Outcome==LibraryOperationOutcome.Cancelled&&File.Exists(Path.Combine(root,"partial-upper.png")),"rename interruption preserves moved original and a step recovery journal");}
                using(MediaRepository reopen=new MediaRepository(root,data)){await reopen.RefreshAsync(CancellationToken.None);result=await GroupOperations.RecoverAsync(reopen,plan.TransactionId,true,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Success&&File.Exists(upper),"rename journal restores a partial group after process restart");}
                await repo.RefreshAsync(CancellationToken.None);group=repo.GetSnapshot().FindGroup(group.GroupId);
                File.WriteAllBytes(Path.Combine(root,"collision-upper.png"),Png(Color.Green));plan=await GroupOperations.PlanRenameAsync(repo,group.GroupId,"collision",CancellationToken.None);Tests.Check(plan.Conflicts.Contains("TARGET_EXISTS"),"planning reports existing target before any rename");
                plan=await GroupOperations.PlanRenameAsync(repo,group.GroupId,"stale",CancellationToken.None);await repo.SetAnnotationsAsync(group.GroupId,group.Revision,false,new[]{"new"},CancellationToken.None);result=await GroupOperations.ExecuteAsync(repo,plan,true,CancellationToken.None);Tests.Check(result.Code=="REVISION_CONFLICT"&&File.Exists(upper),"rename transaction compares saved metadata revision before file moves");
                group=repo.GetSnapshot().FindGroup(group.GroupId);GroupOperationPlan copy=await GroupOperations.PlanCopyAsync(repo,dest,group.GroupId,CancellationToken.None);
                using(CancellationTokenSource cancel=new CancellationTokenSource()){result=await GroupOperations.ExecuteCopyAsync(repo,dest,copy,true,cancel.Token,new Step(n=>cancel.Cancel()));Tests.Check(result.Outcome==LibraryOperationOutcome.Cancelled&&File.Exists(upper)&&dest.GetSnapshot().Groups.Single().Tracks.Count==2,"copy interruption keeps originals and reserves paired destination UUIDs");}
                string copyId=dest.GetSnapshot().Groups.Single().GroupId;await dest.RefreshAsync(CancellationToken.None);Tests.Check(dest.GetSnapshot().Groups.Single().GroupId==copyId,"destination reconcile does not split partial copy into new single-screen groups");
                result=await GroupOperations.RecoverCopyAsync(repo,dest,copy.TransactionId,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Success&&result.RepositoryResult.Group.GroupId==copyId&&File.Exists(upper)&&result.RepositoryResult.Group.Tracks.All(x=>x.State==TrackState.Present),"copy recovery validates bytes and completes destination while preserving source originals");
                Tests.Check(result.RepositoryResult.Group.GroupId!=group.GroupId&&result.RepositoryResult.Group.Tags.Single()=="new", "copied group receives new identity and retains source annotations");
                MediaGroup copied=result.RepositoryResult.Group;await dest.SetAnnotationsAsync(copied.GroupId,copied.Revision,true,new[]{"edited"},CancellationToken.None);result=await GroupOperations.RecoverCopyAsync(repo,dest,copy.TransactionId,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Success&&result.RepositoryResult.Group.Tags.Single()=="edited", "idempotent copy recovery preserves later destination annotation edits");
                Tests.Check((await GroupOperations.PermanentDeleteAsync()).Outcome==LibraryOperationOutcome.Unsupported&&(await GroupOperations.RecycleAsync()).Outcome==LibraryOperationOutcome.Unsupported&&(await GroupOperations.CrossRootMoveAsync()).Outcome==LibraryOperationOutcome.Unsupported,"unvalidated recycle permanent delete and source-deleting move are typed unsupported");
                MediaGroup locked=await Pair(repo,"locked");GroupOperationPlan lockedPlan=await GroupOperations.PlanRenameAsync(repo,locked.GroupId,"unlocked",CancellationToken.None);
                using(FileStream hold=File.Open(Path.Combine(root,"locked-upper.png"),FileMode.Open,FileAccess.Read,FileShare.None)){result=await GroupOperations.ExecuteAsync(repo,lockedPlan,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Failed&&File.Exists(Path.Combine(root,"locked-lower.png")),"locked file rejects rename before moving the peer");}
                File.SetAttributes(Path.Combine(root,"locked-upper.png"),FileAttributes.ReadOnly);plan=await GroupOperations.PlanRenameAsync(repo,locked.GroupId,"readOnly",CancellationToken.None);Tests.Check(plan.Conflicts.Contains("SOURCE_UNAVAILABLE"),"read-only original receives an explicit planning conflict");File.SetAttributes(Path.Combine(root,"locked-upper.png"),FileAttributes.Normal);
                plan=await GroupOperations.PlanRenameAsync(repo,locked.GroupId,"changed",CancellationToken.None);File.WriteAllBytes(Path.Combine(root,"locked-upper.png"),Png(Color.Cyan));result=await GroupOperations.ExecuteAsync(repo,plan,true,CancellationToken.None);Tests.Check(result.Code=="SOURCE_CHANGED"&&File.Exists(Path.Combine(root,"locked-lower.png")),"changed source hash invalidates rename before any file moves");
                MediaGroup review=await Pair(repo,"review");plan=await GroupOperations.PlanRenameAsync(repo,review.GroupId,"reviewMoved",CancellationToken.None);using(CancellationTokenSource cancel=new CancellationTokenSource()){await GroupOperations.ExecuteAsync(repo,plan,true,cancel.Token,new Step(n=>cancel.Cancel()));}await repo.SetAnnotationsAsync(review.GroupId,review.Revision,true,new[]{"user-edited"},CancellationToken.None);result=await GroupOperations.RecoverAsync(repo,plan.TransactionId,true,true,CancellationToken.None);Tests.Check(result.Code=="REVISION_CONFLICT"&&File.Exists(Path.Combine(root,"reviewMoved-upper.png")),"recovery refuses to bypass real user metadata CAS after interruption");
                string journal=Path.Combine(data,"transactions",plan.TransactionId+".thor-rename");File.AppendAllText(journal,"tamper");result=await GroupOperations.RecoverAsync(repo,plan.TransactionId,true,true,CancellationToken.None);Tests.Check(result.Outcome!=LibraryOperationOutcome.Success,"damaged rename journal fails closed and preserves partial originals");
            }
            string importRoot=Folder(),importData=Folder();using(MediaRepository repo=new MediaRepository(importRoot,importData))
            {
                await repo.RefreshAsync(CancellationToken.None);Provider provider=new Provider{Bytes=Png(Color.Purple)};provider.Item=new RemoteMedia("/sdcard/Pictures/Selected","截图.png",provider.Bytes.Length,DateTime.UtcNow,Hash(provider.Bytes));
                ImportScan scan=await DeviceImport.ScanAsync(provider,new[]{provider.Item.Directory},CancellationToken.None);Tests.Check(scan.Outcome==LibraryOperationOutcome.Success&&provider.Listed.SequenceEqual(new[]{provider.Item.Directory}),"offline read-only import lists only the explicitly selected directory");
                DeviceImportPlan plan=DeviceImport.Plan(scan,scan.Items.Single(),repo);GroupOperationResult result=await DeviceImport.ImportAsync(provider,repo,plan,false,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.ConfirmationRequired&&provider.Offsets.Count==0,"import requires selected plan confirmation before remote reads");
                using(CancellationTokenSource cancel=new CancellationTokenSource()){result=await DeviceImport.ImportAsync(provider,repo,plan,true,cancel.Token,new BytesStep(cancel));Tests.Check(result.Outcome==LibraryOperationOutcome.Cancelled&&!File.Exists(Path.Combine(importRoot,"截图.png")),"import cancellation retains partial bytes without publishing incomplete target");}
                result=await DeviceImport.ResumeAsync(provider,repo,plan.TransactionId,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Success&&provider.Offsets.Last()==provider.Bytes.Length&&result.RepositoryResult.Group.Tracks.Single().Role==ScreenRole.Unknown,"import resumes recorded offset and labels imported screen unknown");
                CaptureMetadata meta=CaptureMetadata.Load(Path.Combine(importRoot,"截图.png"));Tests.Check(meta.Status=="device-import"&&meta.Serial.Length==0,"offline import records source marker without leaking device serial");
                result=await DeviceImport.ResumeAsync(provider,repo,plan.TransactionId,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Success&&repo.GetSnapshot().Groups.Count==1,"completed import retry creates no duplicate group");
                DeviceImportPlan duplicate=DeviceImport.Plan(scan,scan.Items.Single(),repo,"copy.png");result=await DeviceImport.ImportAsync(provider,repo,duplicate,true,CancellationToken.None);Tests.Check(result.Code=="DUPLICATE_CONTENT"&&!File.Exists(Path.Combine(importRoot,"copy.png")),"same remote SHA does not duplicate existing imported original");
                provider.Id=Guid.NewGuid();result=await DeviceImport.ResumeAsync(provider,repo,plan.TransactionId,true,CancellationToken.None);Tests.Check(result.Code=="IMPORT_JOURNAL_INVALID","import restart cannot silently bind another provider session");
                provider.Rebind=true;scan=await DeviceImport.ScanAsync(provider,new[]{provider.Item.Directory},CancellationToken.None);Tests.Check(scan.Outcome==LibraryOperationOutcome.Conflict,"provider rebind during directory enumeration fails closed");
                provider.Rebind=false;provider.Bytes=Png(Color.Gold);provider.Item=new RemoteMedia(provider.Item.Directory,"bad.png",provider.Bytes.Length,DateTime.UtcNow,Hash(Png(Color.Cyan)));scan=await DeviceImport.ScanAsync(provider,new[]{provider.Item.Directory},CancellationToken.None);plan=DeviceImport.Plan(scan,scan.Items.Single(),repo);result=await DeviceImport.ImportAsync(provider,repo,plan,true,CancellationToken.None);Tests.Check(result.Code=="SOURCE_HASH_MISMATCH"&&!File.Exists(Path.Combine(importRoot,"bad.png")),"remote content fingerprint mismatch leaves only private partial file");
                provider.Bytes=Png(Color.Green);provider.Item=new RemoteMedia(provider.Item.Directory,"hang.png",provider.Bytes.Length,DateTime.UtcNow,Hash(provider.Bytes));provider.Hang=true;scan=await DeviceImport.ScanAsync(provider,new[]{provider.Item.Directory},CancellationToken.None);plan=DeviceImport.Plan(scan,scan.Items.Single(),repo);result=await DeviceImport.ImportAsync(provider,repo,plan,true,CancellationToken.None);Tests.Check(result.Code=="IMPORT_PROVIDER_TIMEOUT","unresponsive read-only provider has a bounded timeout");
                provider.Hang=false;result=await DeviceImport.ResumeAsync(provider,repo,plan.TransactionId,true,CancellationToken.None);Tests.Check(result.Outcome==LibraryOperationOutcome.Success,"provider timeout releases owned files and permits explicit resume");
            }
        }
    }
}
